INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44511, 'Ezekiel 21:15', 'Ezekiel', 21, 15, 'په دې به زما قوم خپله روحیه له لاسه ورکړي او د وېرې به ولویږي. زه د هغوی د ښار ټولو دروازو ته په یوې داسې تورې خبرداری ورکوم چې د برېښنا په شان ځلیږي او د وژنې دپاره تیاره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_15.mp3', '', 1761754199, 1761754199),
(44512, 'Ezekiel 21:16', 'Ezekiel', 21, 16, 'ای تېرې تورې، ښي او چپ خواته ګوزار کوه! هرې خواته چې تاوېږې ګوزار کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_16.mp3', '', 1761754199, 1761754199),
(44513, 'Ezekiel 21:17', 'Ezekiel', 21, 17, 'زه هم خپل لاسونه پړکوم او خپل قهر سړوم. ما څښتن داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_17.mp3', '', 1761754199, 1761754199),
(44514, 'Ezekiel 21:18', 'Ezekiel', 21, 18, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_18.mp3', '', 1761754199, 1761754199),
(44515, 'Ezekiel 21:19', 'Ezekiel', 21, 19, '«ای فاني انسانه، په دوو لارو باندې چې د بابل پاچا د خپلې تورې سره ورباندې راځي، د هغه ځای نقشه جوړه کړه. دواړه لارې باید د یو وطن نه پیل شي. په هغه ځای کې چې دا لارې سره بېلیږي، نو هلته یوه نښه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_19.mp3', '', 1761754199, 1761754199),
(44516, 'Ezekiel 21:20', 'Ezekiel', 21, 20, 'دا نښه به پاچا ته له یوې خوا د عمونیانو د ربه د ښار لاره وښایي او له بلې خوا به د یهودا او د اورشلیم قوي شوي ښار ته د تللو لاره وښایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_20.mp3', '', 1761754199, 1761754199),
(44517, 'Ezekiel 21:21', 'Ezekiel', 21, 21, 'ځکه د بابل پاچا به د هغې نښې سره ودریږي چې دا دوه لارې په کې بېلې شوې دي. هغه به د لارې د معلومولو دپاره د غشو په خوځولو باندې پچه واچوي، د خپلو بتانو نه به مشوره واخلي او د قربانۍ په اینې باندې به فال وګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_21.mp3', '', 1761754199, 1761754199),
(44518, 'Ezekiel 21:22', 'Ezekiel', 21, 22, 'د ښي خوا نښه اورشلیم ته د تللو اشاره ورکوي. نو هغه به لاړ شي، د لرګیو درنې پایې به را‌واخلي، د جنګ نعره به ووهي، دروازو ته به مخامخ د لرګیو درنې پایې ولګوي او د خاورو ډېرۍ او د کلابندۍ دېوال به جوړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_22.mp3', '', 1761754199, 1761754199),
(44519, 'Ezekiel 21:23', 'Ezekiel', 21, 23, 'د اورشلیم خلک به په دې فال باندې باور ونه کړي چې د هغوی سره به داسې وشي، ځکه چې هغوی ټولو د سولې ټینګ تړون کړی ؤ. خو دا به هغوی ته خپل ګناهونه ور په یاد کړي او د هغوی دپاره به دا یو خبرداری وي چې دوی به ونیول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_23.mp3', '', 1761754199, 1761754199),
(44520, 'Ezekiel 21:24', 'Ezekiel', 21, 24, 'نو دا هغه څه دي چې زه څښتن تعالی یې وایم: ‹ستاسو ګناهونه ښکاره شوي دي. هرڅوک پوهیږي چې تاسو څومره ګناهکاران یئ. ستاسو هر عمل ستاسو د ګناه څرګندوونکی دی. تاسو مجرمان یئ او ستاسو دښمنان به تاسو په زوره ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_24.mp3', '', 1761754199, 1761754199),
(44521, 'Ezekiel 21:25', 'Ezekiel', 21, 25, 'ای د اسراییلو فاسد او بدکاره واکمنه، ستا د سزا ورځ رارسېدلې ده او د اخرنۍ سزا ورځ دې راروانه ده.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_25.mp3', '', 1761754199, 1761754199),
(44522, 'Ezekiel 21:26', 'Ezekiel', 21, 26, 'زه څښتن تعالی داسې وایم: ‹تاج او لونګۍ لېرې کړه. هرڅه به بدل شي. سپک خلک به درانه شي او درانه خلک به سپک شي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_26.mp3', '', 1761754199, 1761754199),
(44523, 'Ezekiel 21:27', 'Ezekiel', 21, 27, 'وراني! وراني! زه به ښار وران کړم. خو‎ تر هغې پورې به دا کار ونه شي، ترڅو هغه څوک چې ما ښار ته د سزا ورکولو دپاره غوره کړی دی، نه وي راغلی. بیا به یې هغه ته ورتسلیم کړم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_27.mp3', '', 1761754199, 1761754199),
(44524, 'Ezekiel 21:28', 'Ezekiel', 21, 28, '«ای فاني انسانه، نبوت وکړه. اعلان وکړه چې زه څښتن تعالی عمونیانو ته چې د اسراییلیانو سپکاوی کوي، وایم. هغوی ته ووایه: ‹یوه توره ستاسو د قتلولو دپاره تیاره ده هغه صیقل شوې ده او د برېښنا په شان ځلیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_28.mp3', '', 1761754199, 1761754199),
(44525, 'Ezekiel 21:29', 'Ezekiel', 21, 29, 'ستاسو پیغمبران غلطې رویاګانې بیانوي او هغه فالونه چې ویني، هغه دروغ دي. هغوی فاسد او بدکاره خلک دي او د هغوی د اخرنۍ سزا وخت راغلی دی. هغه توره به د هغوی په ورمېږ باندې راولویږي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_29.mp3', '', 1761754199, 1761754199),
(44526, 'Ezekiel 21:30', 'Ezekiel', 21, 30, '«‹خپله توره دې بېرته په پوښ کې کېږده! په کوم ځای کې چې ته پیدا شوی یې یعنې ستا د زېږېدنې په اصلي ځای کې به درته سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_30.mp3', '', 1761754199, 1761754199),
(44527, 'Ezekiel 21:31', 'Ezekiel', 21, 31, 'زه به په تا باندې د خپل قهر بلېدونکی اور واچوم او د خپل غضب د اور لمبې به په تا پو کړم. تا به داسې وحشي خلکو ته په لاس ورکړم چې په تباهۍ کې مهارت لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_31.mp3', '', 1761754199, 1761754199),
(44528, 'Ezekiel 21:32', 'Ezekiel', 21, 32, 'ته به د اور دپاره د سوځېدلو مواد شې. وینه به دې په خپل هېواد کې تویه شي او هېڅوک به دې نور نه یادوي.› څښتن داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_32.mp3', '', 1761754199, 1761754199),
(44529, 'Lamentations 2:1', 'Lamentations', 2, 1, 'افسوس، مالِک په خپل قهر د لور صيون نيازبين ښار د شرم سره مخ کړو، هغۀ د اِسرائيل شان و شوکت د آسمان نه زمکې ته راوغورزولو. هغۀ په خپل کور باندې هيڅ رحم ونۀ کړو کله چې هغه په قهر او غضب کښې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_1.mp3', '', 1761754199, 1761754199),
(44530, 'Lamentations 2:2', 'Lamentations', 2, 2, 'مالِک په بې‌رحمۍ سره د يعقوب د اوسېدو ټول ځايونه تباه کړل. او په خپل قهر کښې هغۀ د لور يهوداه د ښار مضبوطې قلعه ګانې راوغورزولې. په بې‌عزتۍ سره هغۀ زمکې ته بادشاهى او د دې بادشاهان راوغورزول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_2.mp3', '', 1761754199, 1761754199),
(44531, 'Lamentations 2:3', 'Lamentations', 2, 3, 'هغۀ په خپل قهر و غضب کښې د اِسرائيلو ټول طاقت ختم کړو. کله چې دشمن حمله وکړه نو مالِک خپل ښے لاس د هغوئ مدد نه وروستو کړو. هغه په اِسرائيل کښې لکه د اور لمبه شو او ګېرچاپېره هر يو شے يې وسوزولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_3.mp3', '', 1761754199, 1761754199),
(44532, 'Lamentations 2:4', 'Lamentations', 2, 4, 'هغۀ لکه د دشمن په شان خپله لينده راښکله او هغۀ خپل ښے لاس لکه د دشمن ګزار ته تيار کړو. هغۀ هغه ټول ووژل څوک چې په مونږ ګران وُو، هغۀ خپل غضب لکه د اور په شان د لور صيون په نيازبينې خېمې راوورولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_4.mp3', '', 1761754199, 1761754199),
(44533, 'Lamentations 2:5', 'Lamentations', 2, 5, 'مالِک د هغوئ د دشمن په شان شو، هغۀ اِسرائيل تباه کړو، هغۀ د هغۀ ټول محلونه تباه کړل، د هغۀ مضبوطې قلعه ګانې يې تباه کړې. هغۀ د لور يهوداه ښار په ماتمونو او مرثيو کښې اضافه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_5.mp3', '', 1761754199, 1761754199),
(44534, 'Lamentations 2:6', 'Lamentations', 2, 6, 'هغۀ خپل کور داسې په آسانه راوغورزولو لکه تۀ به وائې چې په باغ کښې يې جونګړه راوغورزوله، او د عبادت مقدس ځائ يې تباه کړو. مالِک خُدائ په صيون مقدس اخترونه او د سبت د ورځو يادونه هېر کړل. په خپل سخت قهر او غضب کښې يې بادشاه او اِمام دواړه رد کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_6.mp3', '', 1761754199, 1761754199),
(44535, 'Lamentations 2:7', 'Lamentations', 2, 7, 'مالِک خپله قربان‌ګاه سپکه کړه، او خپل مقدس مقام يې پرېښودلو. هغۀ د دشمن لاسونو ته د خپل محلونو دېوالونه حواله کړل. دشمن د مالِک خُدائ په کور کښې چغې کړې لکه څنګه چې د اختر په ورځ خلق کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_7.mp3', '', 1761754199, 1761754199),
(44536, 'Lamentations 2:8', 'Lamentations', 2, 8, 'مالِک خُدائ دا فېصله وکړه چې د صيون ښار دېوالونه وران کړى. هغۀ د ورانولو دپاره د ناپ تول ګز راوغزولو او خپل لاس يې د هغۀ د تباهۍ نه منع نۀ کړو. د هغۀ دېوالونه او د هغۀ مورچې يې په ماتم آخته کړې او دواړه په يو ځائ تباه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_8.mp3', '', 1761754199, 1761754199),
(44537, 'Lamentations 2:9', 'Lamentations', 2, 9, 'د يروشلم دروازې په زمکه کښې ډوبې شوې دى، او د هغې اړمونه او تالې يې تباه کړې دى. د هغې بادشاه او شهزادګان نورو قومونو ته جلاوطن کړے شوى دى. نور د مالِک خُدائ نه شريعت نۀ ملاويږى او نۀ نورې وحى د هغۀ پېغمبرانو ته د مالِک خُدائ نه راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_9.mp3', '', 1761754199, 1761754199),
(44538, 'Lamentations 2:10', 'Lamentations', 2, 10, 'د صيون مشران په زمکه په خاموشۍ سره ناست دى. هغوئ په خپلو سرونو خاورې اچولې دى او د ټاټ جامې يې اغوستې دى. د يروشلم پېغلو جينکو خپل سرونه د شرم نه زمکې ته ټيټ کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_10.mp3', '', 1761754199, 1761754199),
(44539, 'Lamentations 2:11', 'Lamentations', 2, 11, 'زما سترګې د خفګان نه په ژړا ستړې شوې دى. زما زړۀ د غم نه نا آرامه دے. زما زړۀ د خفګان نه چاؤدلے دے، په دې وجه چې زما خلق تباه شوى دى ځکه چې د پيو او واړۀ ماشومان بې‌هوشه دى او د ښار په سړکونو دپاسه مړاوى کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_11.mp3', '', 1761754199, 1761754199),
(44540, 'Lamentations 2:12', 'Lamentations', 2, 12, 'هغوئ خپلو ميندو ته ژاړى چې، ”خوراک او څښاک چرته دے؟“ هغوئ لکه د زخميانو په شان بې‌حاله دى، د ښار په کوڅو کښې بې‌حاله دى او هغوئ د ژوند نه لاس ووينځلو د مور په غېږ کښې د هغوئ ژوند ختم شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_12.mp3', '', 1761754199, 1761754199),
(44541, 'Lamentations 2:13', 'Lamentations', 2, 13, 'زۀ ستا په حقله څۀ ووايم، او د چا سره دې برابره کړمه؟ اے يروشلم لورې، تا د څۀ سره مقايسه کړمه چې تا ته تسلى درکړمه؟ اے صيون پېغلې لورې، د سمندر د ژوروالى په اندازه ستا تباهى ده، څوک به تا ته شفا درکړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_13.mp3', '', 1761754199, 1761754199),
(44542, 'Lamentations 2:14', 'Lamentations', 2, 14, 'ستا پېغمبرانو ستا دپاره بې‌مطلبه او دوکه مارې روياګانې وليدلې. هغوئ ستاسو ګناهونه ښکاره نۀ کړل چې تاسو د جلاوطنۍ نه بچ کړى. خو تاسو ته يې د دروغو او بې‌لارې کوونکى پېغامونه واورول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_14.mp3', '', 1761754199, 1761754199),
(44543, 'Lamentations 2:15', 'Lamentations', 2, 15, 'هغوئ ټول څوک چې په دې لاره تېريږى هغوئ تا پورې ملنډى وهى. هغوئ د مسخرو نه خپل سرونه خوځوى او د لور يروشلم ښار پورې خندا کوى. ”آيا دا هغه ښار نۀ وو کوم به چې يادېدو، او په خپل ښائست کښې بې‌عېبه وو، او د ټولې دُنيا د خوشحالۍ سبب وو؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_15.mp3', '', 1761754199, 1761754199),
(44544, 'Lamentations 2:16', 'Lamentations', 2, 16, 'ستا ټول دشمنان تا پورې خندا کوى، او ستا خلاف يې خپلې خولې کولاو کړې دى، هغوئ نېغ نېغ ګورى او خپل غاښونه چيچى، او هغوئ چغې وهى چې، ”مونږ هغه لواړه تېره کړه. مونږ د دې ورځ انتظار کولو او آخر مو وليدله.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_16.mp3', '', 1761754199, 1761754199),
(44545, 'Lamentations 2:17', 'Lamentations', 2, 17, 'نو مالِک خُدائ خپل مقصد پوره کړو، هغۀ د خپل مقصد خبردارے ورکړو، چې د ډېر پخوا نه يې خبردارے ورکړے وو، هغۀ په بې‌رحمۍ سره هر څۀ تباه کړل. هغۀ ستا دشمنان په تا خوشحاله کړل او هغۀ ستا د دشمنانو زور په تا اوچت کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_17.mp3', '', 1761754199, 1761754199),
(44546, 'Lamentations 2:18', 'Lamentations', 2, 18, 'مالِک ته په زوره چغې ووهه، اے د نيازبين صيون لور دېوالونو، د اوښکو نِهرونه دې لکه د سېلاب په شان وبهيږى، په شپه او ورځ کښې دې وبهيږى. خپل ځان ته آرام مۀ ورکوه او په سترګو دې ژړا مۀ بندوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_18.mp3', '', 1761754199, 1761754199),
(44547, 'Lamentations 2:19', 'Lamentations', 2, 19, '”راپاڅه، او په شپه کښې ژړا وکړه، په هره شېبه کښې د مالِک په حضور کښې د خپل زړۀ حال راڅرګند کړه. او خپل لاسونه هغۀ ته پورته کړه د خپلو ماشومانو د ژوند دپاره څوک چې د کوڅو په هر ګوټ کښې د لوږى نه مړۀ کيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_19.mp3', '', 1761754199, 1761754199),
(44548, 'Lamentations 2:20', 'Lamentations', 2, 20, 'وګوره، اے مالِکه خُدايه، او غور وکړه. تا داسې د چا سره کړى دى؟ ولې ميندې دې خپل ماشومان خورى چې هغوئ زيږولى دى؟ ولې اِمامان او پېغمبران دې د مالِک په مقدس کور کښې قتل کړے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_20.mp3', '', 1761754199, 1761754199),
(44549, 'Lamentations 2:21', 'Lamentations', 2, 21, 'زاړۀ او زلمى په کوڅو کښې پراتۀ دى، په زمکه په کوڅو کښې زما ځوانې ښځې او ځوانان سړى په تُوره راغورزولے شوى دى. د خپل قهر په ورځو کښې تا هغوئ مړۀ کړل او په بې‌رحمۍ سره مو حلال کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_21.mp3', '', 1761754199, 1761754199),
(44550, 'Lamentations 2:22', 'Lamentations', 2, 22, 'تا د هرې خوا نه زما دشمنانو له دعوت ورکړو لکه چې د اختر د ورځ دپاره دې راغوښتى وى. او د مالِک خُدائ د قهر په ورځو کښې نه څوک تښتېدلے شُو او نه څوک بچ کېدلے شُو. هغوئ څوک چې ما زيږولى وُو او په ما ګران وُو زما دشمن هغه تباه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations2_verse_22.mp3', '', 1761754199, 1761754199),
(44551, 'Ecclesiastes 2:1', 'Ecclesiastes', 2, 1, 'له ځان سره مې وویل: «راځه چې عیش او عشرت وازمایم ترڅو له ژوند نه خوند واخلم.» خو چې ومې لیدل دا حالت هم لوګی او پوکی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_1.mp3', '', 1761754199, 1761754199),
(44552, 'Ecclesiastes 2:2', 'Ecclesiastes', 2, 2, 'نو ما فکر وکړ چې خندا او خوشحالي جهالت دی او د عیش او عشرت ګټه څه ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_2.mp3', '', 1761754199, 1761754199),
(44553, 'Ecclesiastes 2:3', 'Ecclesiastes', 2, 3, 'په داسې حال کې چې حکمت لا هم زما د زړه لارښوونه کوله، نو ومې غوښتل دا وڅېړم چې څنګه ځان په شرابو خوشحاله او په حماقت کې ډوب کړم. غوښتل مې وګورم چې د انسانانو دپاره څه شی ښه دی چې د خپل ژوند په لنډه موده کې یې تر‌سره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_3.mp3', '', 1761754199, 1761754199),
(44554, 'Ecclesiastes 2:4', 'Ecclesiastes', 2, 4, 'ما د خپل ځان دپاره لوی لوی کارونه وکړل. ما کورونه ودان کړل او د انګورو تاکونه مې کښېنول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_4.mp3', '', 1761754199, 1761754199),
(44555, 'Ecclesiastes 2:5', 'Ecclesiastes', 2, 5, 'د ځان دپاره مې باغونه او پارکونه جوړ کړل او په هغو کې مې ډول ډول د مېوو ونې کښېنولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_5.mp3', '', 1761754199, 1761754199),
(44556, 'Ecclesiastes 2:6', 'Ecclesiastes', 2, 6, 'ما د راشنو شویو ونو د خړوبولو دپاره د اوبو ډنډونه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_6.mp3', '', 1761754199, 1761754199),
(44557, 'Ecclesiastes 2:7', 'Ecclesiastes', 2, 7, 'ما غلامان او وینځې واخیستلې او په کور کې مې نور غلامان او وینځې هم زېږېدلې وې. زه د ډېرو رمو او پادو خاوند شوم. زما څاروي دومره ډېر وو چې زما څخه مخکې په اورشلیم کې هېچا نه درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_7.mp3', '', 1761754199, 1761754199),
(44558, 'Ecclesiastes 2:8', 'Ecclesiastes', 2, 8, 'ما د خپل لاس لاندې سیمو څخه د ځان دپاره سره او سپین زر او د پاچاهانو شتمني راټوله کړه. ما ښځینه او نارینه سندرغاړي راټول کړل او خپل حرمسرای مې له ښایسته ښځو نه ډک کړ چې سړیو یې د عیش او عشرت ارمان کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_8.mp3', '', 1761754199, 1761754199),
(44559, 'Ecclesiastes 2:9', 'Ecclesiastes', 2, 9, 'نو زه دومره لوی او ځواکمن شوم چې زما څخه مخکې په اورشلیم کې داسې ځواکمن سړی نه ؤ تېر شوی او ما خپل حکمت هم له لاسه ورنه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_9.mp3', '', 1761754199, 1761754199),
(44560, 'Ecclesiastes 2:10', 'Ecclesiastes', 2, 10, 'ما د خپل زړه هر ارمان پوره کاوه. ما د هېڅ ډول عیش او عشرت نه ځان بې‌برخې نه کړ. زه د دې ټولو له زیار او زحمت نه ډکو کارونو څخه چې ما تر‌سره کړي وو، خوشحاله وم او دا خوشحالي زما د دې زحمتونو انعام ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_10.mp3', '', 1761754199, 1761754199),
(44561, 'Ecclesiastes 2:11', 'Ecclesiastes', 2, 11, 'نو بیا مې په خپلو ټولو هغو کارونو چې ما کړي وو او ټولو هغو زحمتونو چې د هغو د تر‌لاسه کولو دپاره مې ویستلي وو، فکر وکړ. نو ومې لیدل چې دا هرڅه لوګی او پوکی، په باد پسې منډې وهل او د اسمان لاندې د هېڅ ګټې تر‌لاسه کول وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_11.mp3', '', 1761754199, 1761754199),
(44562, 'Ecclesiastes 2:12', 'Ecclesiastes', 2, 12, 'بیا ما پرېکړه وکړه چې په حکمت، جهالت او حماقت باندې غور او فکر وکړم. ځکه کوم کس چې له پاچا څخه وروسته راځي هغه نور څه کولای شي، پرته له هغه څه چې پخوا هم شوي وو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_12.mp3', '', 1761754199, 1761754199),
(44563, 'Ecclesiastes 2:13', 'Ecclesiastes', 2, 13, 'نو ماته معلومه شوه چې لکه څنګه چې په رڼا کې له تیارې نه ګټه ډېره ده همداسې په حکمت کې د حماقت نه ګټه ډېره ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_13.mp3', '', 1761754199, 1761754199),
(44564, 'Ecclesiastes 2:14', 'Ecclesiastes', 2, 14, 'هوښیار انسان په رڼا کې روان وي خو کم‌عقل انسان په تیاره کې روان وي نو زه دې نتیجې ته ورسېدم چې د دواړو انجام یو دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_14.mp3', '', 1761754199, 1761754199),
(44565, 'Ecclesiastes 2:15', 'Ecclesiastes', 2, 15, 'بیا مې له ځان سره وویل: «هغه څه چې په کم‌عقل انسان باندې پېښیږي په ما به هم پېښ شي. بیا نو زه د حکمت په حاصلولو سره څه ګټه تر‌لاسه کوم؟» او بیا مې له ځان سره وویل: «دا حالت هم لوګی او پوکی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_15.mp3', '', 1761754199, 1761754199),
(44566, 'Ecclesiastes 2:16', 'Ecclesiastes', 2, 16, 'ځکه داسې وخت به راشي چې هوښیار انسان به هم د کم‌عقل انسان په شان تل په یاد پاتې نه شي او دواړه به هېر شي. افسوس چې هوښیار انسان به هم لکه د کم‌عقل انسان په شان مړ کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_16.mp3', '', 1761754199, 1761754199),
(44567, 'Ecclesiastes 2:17', 'Ecclesiastes', 2, 17, 'نو بیا مې زړه له ژوند نه تور شو، ځکه هغه څه چې د اسمان لاندې تر‌سره کیږي زه یې ډېر په تکلیف کړی وم. نو دا هرڅه لوګي او پوکي او په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_17.mp3', '', 1761754199, 1761754199),
(44568, 'Ecclesiastes 2:18', 'Ecclesiastes', 2, 18, 'د هغو ټولو شیانو دپاره چې د هغو په خاطر مې د یو مزدور په څېر د اسمان لاندې زحمتونه ویستلي وو، زما سره کرکه پیدا شوه، ځکه چې دا هرڅه باید هغه چاته پرېږدم چې زما څخه وروسته راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_18.mp3', '', 1761754199, 1761754199),
(44569, 'Ecclesiastes 2:19', 'Ecclesiastes', 2, 19, 'څوک پوهیږي چې دغه کس به هوښیار وي یا کم عقل؟ خو بیا به هم هغه د ټولو هغو شیانو خاوند شي د کوم دپاره چې ما د اسمان لاندې زیار او زحمت ویستلی دی او له خپل حکمت نه مې کار اخیستلی دی، ترڅو هغه تر‌لاسه کړم. نو دا حالت هم لوګی او پوکی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_19.mp3', '', 1761754199, 1761754199),
(44570, 'Ecclesiastes 2:20', 'Ecclesiastes', 2, 20, 'نو بیا ما په دې اړه فکر وکړ او زه د هغو ټولو له زیار او زحمت نه ډکو کارونو څخه ناهیلی شوم چې د اسمان لاندې مې ویستلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_20.mp3', '', 1761754199, 1761754199),
(44571, 'Ecclesiastes 2:21', 'Ecclesiastes', 2, 21, 'دا ځکه چې یو انسان به په حکمت، پوهې او لیاقت سره زیار او زحمت وباسي او یو څه به حاصل کړي، خو وروسته به خپله برخه هغه چاته پرېږدي چې د هغو دپاره یې هېڅ زیار او زحمت نه دی ویستلی. نو دا حالت هم لوګی او پوکی او لویه بدبختي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_21.mp3', '', 1761754199, 1761754199),
(44572, 'Ecclesiastes 2:22', 'Ecclesiastes', 2, 22, 'نو انسان د دې ټولو زحمتونو او هلو ځلو څخه چې د یو مزدور په څېر یې د اسمان لاندې وباسي، څه تر‌لاسه کوي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_22.mp3', '', 1761754199, 1761754199),
(44573, 'Ecclesiastes 2:23', 'Ecclesiastes', 2, 23, 'هغه د دردونو نه ډکې ورځې تېروي او ټول کارونه یې سخت او له کړاوونو نه ډک دي. حتی د شپې له خوا به هم د هغه زړه ارامه نه وي. نو دا حالت هم لوګی او پوکی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_23.mp3', '', 1761754199, 1761754199),
(44574, 'Ecclesiastes 2:24', 'Ecclesiastes', 2, 24, 'نو دا ټول نعمتونه چې انسان یې خوري او څښي او له خپل زیار او زحمت نه خوند اخلي، د هغه له خوا نه دي، بلکې لکه څنګه چې ماته معلومه شوه، د خدای له خوا دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_24.mp3', '', 1761754199, 1761754199),
(44575, 'Ecclesiastes 2:25', 'Ecclesiastes', 2, 25, 'په حقیقت کې، هېڅوک زما په شان نه شي کولای چې څه وخوري او له خپل ژوند نه خوند واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_25.mp3', '', 1761754199, 1761754199),
(44576, 'Ecclesiastes 2:26', 'Ecclesiastes', 2, 26, 'ځکه هرڅوک چې خدای راضي او خوشحاله کړي، نو خدای هم هغه ته پوهه، حکمت او خوشحالي ورکوي. خو ګناهکارانو ته د مال او دولت د راټولولو او ذخیره کولو سخت کار ور په برخه کوي او بیا یې ترې نه بېرته اخلي او هغه چاته یې ورکوي چې خدای ترې راضي او خوشحاله وي. نو دا حالت هم لوګی او پوکی او په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes2_verse_26.mp3', '', 1761754199, 1761754199),
(44577, 'Exodus 26:1', 'Exodus', 26, 1, 'د لسو داسې پردو څخه یوه سپېڅلې خېمه جوړه کړه چې د ښه کتان او د ابي، بانجاني او سرو وړیو څخه وي او په پردو کې یې د اسماني مخلوقاتو نقشونه ګلدوزي شوی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_1.mp3', '', 1761754199, 1761754199),
(44578, 'Exodus 26:2', 'Exodus', 26, 2, 'د ټولو پردو اندازه دې یوشان وي، دولس متره دې اوږدې او دوه متره دې پلنې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_2.mp3', '', 1761754199, 1761754199),
(44579, 'Exodus 26:3', 'Exodus', 26, 3, 'د دې پردو څخه پنځه په یوه جوړه کې سره یوځای کړه او بیا نورې پنځه پردې په دوهمه جوړه کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_3.mp3', '', 1761754199, 1761754199),
(44580, 'Exodus 26:4', 'Exodus', 26, 4, 'په هره جوړه کې د باندینۍ پردې په څنډه باندې د ابي رنګه ټوټې کړۍ ګانې جوړې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_4.mp3', '', 1761754199, 1761754199),
(44581, 'Exodus 26:5', 'Exodus', 26, 5, 'پنځوس کړۍ ګانې په یوې پردې باندې او پنځوس د بلې جوړې په اخرنۍ پردې باندې جوړې کړه چې دا کړۍ ګانې یو بل ته مخامخ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_5.mp3', '', 1761754199, 1761754199),
(44582, 'Exodus 26:6', 'Exodus', 26, 6, 'بیا د سرو زرو پنځوس چنګکونه جوړ کړه او د پردو په یوځای تړلو کې ورڅخه کار واخله، ترڅو ټوله یوه خېمه ورڅخه جوړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_6.mp3', '', 1761754199, 1761754199),
(44583, 'Exodus 26:7', 'Exodus', 26, 7, 'د خېمې د پټولو دپاره د وزو د وړیو څخه پردې جوړې کړه. ټولې دې یوولس دانې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_7.mp3', '', 1761754199, 1761754199),
(44584, 'Exodus 26:8', 'Exodus', 26, 8, 'یوولس واړه پردې دې په یوه اندازه وي، یعنې دیارلس متره اوږدوالی او دوه متره سور ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_8.mp3', '', 1761754199, 1761754199),
(44585, 'Exodus 26:9', 'Exodus', 26, 9, 'پنځه پردې په یوه جوړه کې یو تر بله سره وګنډه او نورې شپږ په بله جوړه کې. شپږمه پرده د خېمې په مخکینۍ برخه کې سره غبرګه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_9.mp3', '', 1761754199, 1761754199),
(44586, 'Exodus 26:10', 'Exodus', 26, 10, 'پنځوس کړۍ ګانې د یوې جوړې د اخرنۍ پردې په څنډه کې او پنځوس د بلې جوړې د اخرنۍ پردې په څنډه کې جوړې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_10.mp3', '', 1761754199, 1761754199),
(44587, 'Exodus 26:11', 'Exodus', 26, 11, 'بیا د برنجو پنځوس چنګکونه جوړ کړه او په کړیو کې یې واچوه چې خېمه سره ونښلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_11.mp3', '', 1761754199, 1761754199),
(44588, 'Exodus 26:12', 'Exodus', 26, 12, 'د دې پردو اضافه نیمه برخه دې د خېمې شاته ځوړنده شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_12.mp3', '', 1761754199, 1761754199),
(44589, 'Exodus 26:13', 'Exodus', 26, 13, 'د پردې دواړو خواو ته چې نیم متر زیات شوی دی، هغه به راځوړند وي چې خېمه ورباندې پټه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_13.mp3', '', 1761754199, 1761754199),
(44590, 'Exodus 26:14', 'Exodus', 26, 14, 'د خېمې دپاره د پسه د داسې پوستکي څخه پوښ جوړ کړه چې سور رنګ ورکړل شوی وي او په هغه باندې د ښې څرمنې څخه یو پوښ جوړ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_14.mp3', '', 1761754199, 1761754199),
(44591, 'Exodus 26:15', 'Exodus', 26, 15, 'د خېمې دپاره د اکاسۍ د لرګي څخه ولاړ چوکاټونه جوړ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_15.mp3', '', 1761754199, 1761754199),
(44592, 'Exodus 26:16', 'Exodus', 26, 16, 'هر چوکاټ دې څلورنیم متره اوږد او پنځه شپېته سانتي پلن وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_16.mp3', '', 1761754199, 1761754199),
(44593, 'Exodus 26:17', 'Exodus', 26, 17, 'او باید دوه یوشان نښلوونکې تختې ولري، ترڅو چوکاټونه سره یوځای شي. ټول چوکاټونه دې دا تختې ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_17.mp3', '', 1761754199, 1761754199),
(44594, 'Exodus 26:18', 'Exodus', 26, 18, 'د خېمې د جنوب خوا دپاره شل چوکاټونه جوړ کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_18.mp3', '', 1761754199, 1761754199),
(44595, 'Exodus 26:19', 'Exodus', 26, 19, 'او څلوېښت د سپینو زرو پایې چې ورلاندې شي، د هر چوکاټ لاندې دې دوه دوه پایې وي د دې دپاره چې دوه تختې یې ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_19.mp3', '', 1761754199, 1761754199),
(44596, 'Exodus 26:20', 'Exodus', 26, 20, 'د خېمې د شمال خوا دپاره شل چوکاټونه جوړ کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_20.mp3', '', 1761754199, 1761754199),
(44597, 'Exodus 26:21', 'Exodus', 26, 21, 'او څلوېښت د سپینو زرو پایې جوړې کړه چې د هر چوکاټ لاندې دوه دوه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_21.mp3', '', 1761754199, 1761754199),
(44598, 'Exodus 26:22', 'Exodus', 26, 22, 'د خېمې د شا دپاره چې د لوېدیځ خواته ده، شپږ چوکاټونه جوړ کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_22.mp3', '', 1761754199, 1761754199),
(44599, 'Exodus 26:23', 'Exodus', 26, 23, 'او دوه چوکاټونه د خېمې شاته کنجونو دپاره جوړ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_23.mp3', '', 1761754199, 1761754199),
(44600, 'Exodus 26:24', 'Exodus', 26, 24, 'دا چوکاټونه باید په دغو دوو کنجونو کې د بېخ څخه نیولې تر سره پورې سره غبرګ کړای شي او په یوې کړۍ کې ولګول شي. دا دواړه کنجونه دې په همدې شان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_24.mp3', '', 1761754199, 1761754199),
(44601, 'Exodus 26:25', 'Exodus', 26, 25, 'نو اته چوکاټونه او شپاړس د سپینو زرو پایې به وي، د هر چوکاټ لاندې به دوه دوه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_25.mp3', '', 1761754199, 1761754199),
(44602, 'Exodus 26:26', 'Exodus', 26, 26, 'د اکاسۍ د لرګي څخه پنځلس اړمونه جوړ کړه، پنځه د هغو چوکاټونو دپاره جوړ کړه چې د خېمې په یوې خوا باندې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_26.mp3', '', 1761754199, 1761754199),
(44603, 'Exodus 26:27', 'Exodus', 26, 27, 'پنځه د هغو چوکاټونو دپاره چې په بلې خوا باندې دي او پنځه د هغو چوکاټونو دپاره چې شاته د لوېدیځ خواته په اخر سر کې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_27.mp3', '', 1761754199, 1761754199),
(44604, 'Exodus 26:28', 'Exodus', 26, 28, 'منځنی اړم دې د چوکاټونو تر نیمایي پورې کېښودل شي او د خېمې له یو سر څخه دې تر بل سره پورې وغزیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_28.mp3', '', 1761754199, 1761754199),
(44605, 'Exodus 26:29', 'Exodus', 26, 29, 'چوکاټونو ته د سرو زرو پوښ ورکړه او په هغو باندې د سرو زرو کړۍ ګانې ولګوه چې اړمونه ونیسي او هغو ته هم باید د سرو زرو پوښ ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_29.mp3', '', 1761754199, 1761754199),
(44606, 'Exodus 26:30', 'Exodus', 26, 30, 'خېمه د هغې نقشې له مخې جوړه کړه چې ما په غره باندې درته دروښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_30.mp3', '', 1761754199, 1761754199),
(44607, 'Exodus 26:31', 'Exodus', 26, 31, 'د ابي، بانجاني او سرو وړیو او د ښه کتان څخه یوه پرده جوړه کړه چې د اسماني مخلوقاتو داسې نقش په کې وي چې ګلدوزي شوی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_31.mp3', '', 1761754199, 1761754199),
(44608, 'Exodus 26:32', 'Exodus', 26, 32, 'د اکاسۍ د لرګي په څلورو ستنو باندې چې د سرو زرو پوښ ورته ورکړل شوی وي او د سپینو زرو په څلورو پایو باندې ولاړې وي، پرده د سرو زرو په چنګکونو باندې راځوړنده کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_32.mp3', '', 1761754199, 1761754199),
(44609, 'Exodus 26:33', 'Exodus', 26, 33, 'پرده د چنګکونو څخه راځوړنده کړه او د پردې شاته د لوظ صندوق چې دوه د تیږو لوحې په کې دي کېږده. دا پرده به سپېڅلی ځای د ډېر سپېڅلي ځای څخه بېل کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_33.mp3', '', 1761754199, 1761754199),
(44610, 'Exodus 26:34', 'Exodus', 26, 34, 'د لوظ په صندوق باندې چې په ډېر سپېڅلي ځای کې پروت دی، سرپوښ کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_34.mp3', '', 1761754199, 1761754199);